-- Aprenda se Divertindo · 59 · Trilha Policial · lote extra 9 (adaptado das provas PM-PR, PC-PI e PF de 2025) (100 questões)
-- Rode depois do 58-admin-questoes.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":6339,"materia":"rl","nivel":1,"enunciado":"A negação de \"Se o alarme tocou, então a viatura foi acionada\" é:","opcoes":["O alarme tocou e a viatura não foi acionada","O alarme não tocou e a viatura foi acionada","Se o alarme não tocou, a viatura não foi acionada","O alarme não tocou ou a viatura foi acionada"],"explicacao":"Nega-se o \"se A, então B\" com \"A e não B\"."},{"id":6340,"materia":"rl","nivel":2,"enunciado":"Uma companhia recebeu 50 armas, entre pistolas e fuzis. Outra recebeu o dobro das pistolas e o triplo dos fuzis da primeira, num total de 120. Quantas pistolas a primeira recebeu?","opcoes":["30","20","25","35"],"explicacao":"p + f = 50 e 2p + 3f = 120. Logo f = 20 e p = 30."},{"id":6341,"materia":"rl","nivel":0,"enunciado":"Um sargento quer dar 12 coletes a cada membro da equipe, mas tem 170 e faltariam 10 para isso. Quantos são os membros da equipe?","opcoes":["15","14","16","18"],"explicacao":"170 + 10 = 180 coletes; 180 ÷ 12 = 15 membros."},{"id":6342,"materia":"rl","nivel":0,"enunciado":"20 policiais patrulham 400 km² num turno. Se a área aumentar 25% e o turno for o mesmo, serão necessários:","opcoes":["25 policiais","24 policiais","30 policiais","45 policiais"],"explicacao":"Grandezas diretamente proporcionais: 20 × 1,25 = 25."},{"id":6343,"materia":"rl","nivel":2,"enunciado":"Foi apreendido um frasco com 2 litros de uma solução a 2,5 mg/mL de certa substância. A quantidade total da substância é:","opcoes":["5 g","2,5 g","50 g","0,5 g"],"explicacao":"2.000 mL × 2,5 mg/mL = 5.000 mg = 5 g."},{"id":6344,"materia":"rl","nivel":0,"enunciado":"De 80 detidos, 35 têm passagem por tráfico, 30 por porte de arma e 12 por ambos. Quantos não têm passagem por nenhum dos dois?","opcoes":["27","15","23","3"],"explicacao":"35 + 30 − 12 = 53 com alguma passagem; 80 − 53 = 27."},{"id":6345,"materia":"rl","nivel":3,"enunciado":"Três suspeitos mentiram. X disse: \"nem Y nem Z são culpados\". Z disse: \"os culpados são Y e X\". Y disse: \"o culpado é Z ou X\". Quem é o culpado?","opcoes":["Y","X","Z","X e Z"],"explicacao":"Se Y mentiu, nem Z nem X são culpados. Logo o culpado é Y, o que também torna falsas as falas de X e Z."},{"id":6346,"materia":"rl","nivel":4,"enunciado":"São verdadeiras: \"Se Paulo é parente da vítima, ele é inocente e estava viajando\" e \"Se Paulo tem o sobrenome ou o tipo sanguíneo da vítima, ele é parente dela\". Se Paulo não estava viajando, conclui-se que ele:","opcoes":["Não tem o mesmo tipo sanguíneo da vítima","É culpado pelo crime investigado","Tem o mesmo sobrenome da vítima","É parente próximo da vítima"],"explicacao":"Sem viagem, ele não é parente (modus tollens); sem parentesco, não tem nem o sobrenome nem o tipo sanguíneo."},{"id":6347,"materia":"rl","nivel":2,"enunciado":"Vale a frase: \"Se Aldo ou Bruno é filho de Carlos, então Daniel é pai de Elza e de Fernanda\". Se Elza não é filha de Daniel, então:","opcoes":["Carlos não é pai de Aldo nem de Bruno","Carlos é pai de Aldo, mas não de Bruno","Daniel é pai só de Fernanda","Bruno é filho de Daniel e de Carlos"],"explicacao":"O consequente é falso; para a condicional ser verdadeira, o antecedente também tem de ser falso."},{"id":6348,"materia":"rl","nivel":4,"enunciado":"Num posto, 200 de 1.000 veículos estavam irregulares. Sorteando 2 placas diferentes, a chance de uma ser de veículo irregular e a outra de regular fica perto de:","opcoes":["32%","16%","20%","64%"],"explicacao":"2 × (200/1000) × (800/999) ≈ 0,32."},{"id":6349,"materia":"rl","nivel":2,"enunciado":"Dos 200 veículos irregulares, 120 tinham problema no documento do veículo, 85 no do condutor e 40 na carga (estes sem outro problema). Quantos tinham problema no veículo e no condutor ao mesmo tempo?","opcoes":["45","40","35","5"],"explicacao":"Sobram 160 com problema de veículo ou condutor: 120 + 85 − 160 = 45."},{"id":6350,"materia":"rl","nivel":4,"enunciado":"Um computador lista todas as ordenações de 8 caracteres distintos em 23 segundos. No mesmo ritmo, para 12 caracteres levaria cerca de:","opcoes":["3 dias e 4 horas","3 horas e 6 minutos","34 minutos","12 dias e meio"],"explicacao":"12!/8! = 9 × 10 × 11 × 12 = 11.880; 23 × 11.880 = 273.240 s ≈ 3 dias, 3 h e 54 min."},{"id":6351,"materia":"est","nivel":1,"enunciado":"Se todos os 30 alunos de uma turma tiraram 10 na prova, o desvio-padrão das notas é:","opcoes":["0","10","1","30"],"explicacao":"Sem variação entre as notas, o desvio-padrão é zero."},{"id":6352,"materia":"est","nivel":3,"enunciado":"Numa amostra de 36 contratos, a diferença média entre valor licitado e pago foi R$ 5 mil, com desvio-padrão de R$ 3 mil. O erro-padrão da média é:","opcoes":["R$ 0,5 mil","R$ 3 mil","R$ 1,5 mil","R$ 0,08 mil"],"explicacao":"Erro-padrão = desvio ÷ √n = 3 ÷ 6 = 0,5."},{"id":6353,"materia":"cont","nivel":1,"enunciado":"Uma dívida com fornecedores que vence em 9 meses aparece no balanço como:","opcoes":["Passivo circulante","Ativo circulante","Patrimônio líquido","Passivo não circulante"],"explicacao":"Obrigações que vencem até o fim do exercício seguinte (12 meses) são passivo circulante."},{"id":6354,"materia":"cont","nivel":2,"enunciado":"Um seguro de R$ 24 mil por 24 meses, com vigência a partir de março, foi pago em fevereiro e março. Pelo regime de competência, a despesa de abril é:","opcoes":["R$ 1.000","R$ 12.000","R$ 24.000","Zero"],"explicacao":"A despesa acompanha a vigência: 24.000 ÷ 24 = R$ 1.000 por mês, a partir de março."},{"id":6355,"materia":"inf","nivel":0,"enunciado":"No celular Android, dá para usar Wi-Fi e Bluetooth ao mesmo tempo?","opcoes":["Sim, os dois funcionam juntos","Não, só uma conexão por vez","Só com um aplicativo pago","Só com o chip desligado"],"explicacao":"Basta ativar os dois nas Configurações ou no painel rápido."},{"id":6356,"materia":"inf","nivel":0,"enunciado":"Um arquivo marcado como oculto no Windows:","opcoes":["Aparece se ativar a exibição de itens ocultos","Fica bloqueado até para o administrador","É apagado sempre que o computador reinicia","Só pode ser aberto pelo antivírus instalado"],"explicacao":"Ocultar só esconde da listagem padrão; não impede o acesso."},{"id":6357,"materia":"inf","nivel":1,"enunciado":"No Windows, arquivos DLL servem principalmente para:","opcoes":["Guardar funções usadas por vários programas","Armazenar fotos e vídeos em alta resolução","Fazer cópia de segurança automática do sistema","Bloquear vírus que chegam por e-mail"],"explicacao":"As bibliotecas de vínculo dinâmico evitam repetir o mesmo código em cada programa."},{"id":6358,"materia":"inf","nivel":0,"enunciado":"O computador funciona, mas a impressora não recebe os trabalhos. Uma causa provável é:","opcoes":["Problema no driver da impressora","Falta de memória RAM no mouse sem fio","Brilho do monitor no mínimo","Teclado sem pilha"],"explicacao":"O driver faz a comunicação entre o sistema e a impressora; reinstalá-lo costuma resolver."},{"id":6359,"materia":"inf","nivel":0,"enunciado":"Numa rede interna, vários servidores podem abrir e editar o mesmo arquivo de uma pasta compartilhada quando:","opcoes":["Têm permissão de acesso a essa pasta","Usam todos o mesmo modelo de teclado","Desligam o antivírus antes de abrir","Estão sentados na mesma sala"],"explicacao":"O compartilhamento em rede depende das permissões dadas a cada usuário."},{"id":6360,"materia":"inf","nivel":1,"enunciado":"Para buscar \"edital\" apenas no site da Polícia Federal, digita-se no Google:","opcoes":["edital site:gov.br/pf","edital in:gov.br/pf","edital @gov.br/pf","edital url=gov.br/pf"],"explicacao":"O operador site: limita a busca a um domínio."},{"id":6361,"materia":"inf","nivel":0,"enunciado":"O LibreOffice Writer consegue salvar o documento direto em PDF?","opcoes":["Sim, pela opção Exportar como PDF","Não, só com outro programa","Só se o texto tiver imagens","Só na versão paga"],"explicacao":"Ele exporta para PDF nativamente, até com marcadores de navegação."},{"id":6362,"materia":"inf","nivel":1,"enunciado":"No Word, para pôr \"MINUTA\" em diagonal e transparente no fundo de todas as páginas, usa-se:","opcoes":["Marca-d'água, na guia Design","Comentários, na guia Revisão","Estilos, na Página Inicial","Cabeçalho, na guia Inserir"],"explicacao":"Fica no grupo Plano de Fundo da Página, da guia Design."},{"id":6363,"materia":"inf","nivel":3,"enunciado":"No protocolo HTTP, o método que pede ao servidor para devolver a própria requisição recebida, útil para diagnóstico, é:","opcoes":["TRACE","HEAD","PUT","POST"],"explicacao":"O TRACE ecoa a requisição; o HEAD traz só os cabeçalhos; o PUT envia um recurso."},{"id":6364,"materia":"inf","nivel":4,"enunciado":"No HTTP, o método usado para perguntar ao servidor quais métodos ele aceita para um recurso é:","opcoes":["OPTIONS","TRACE","CONNECT","GET"],"explicacao":"O OPTIONS lista os métodos e cabeçalhos permitidos."},{"id":6365,"materia":"inf","nivel":3,"enunciado":"Dispositivo físico próprio para guardar chaves criptográficas e gerar assinaturas digitais com segurança:","opcoes":["HSM (módulo de segurança de hardware)","Switch de rede gerenciável de 24 portas","SSD comum de notebook corporativo","Leitor de código de barras"],"explicacao":"O HSM protege as chaves dentro de um hardware resistente a violação."},{"id":6366,"materia":"inf","nivel":4,"enunciado":"No Firefox, o recurso que guarda os cookies de cada site num \"pote\" separado, dificultando o rastreamento entre sites, chama-se:","opcoes":["Total Cookie Protection","Privacy Sandbox","Modo de Leitura","Container Cookies"],"explicacao":"Cada site tem sua própria cookie jar; o Privacy Sandbox é uma proposta do Google."},{"id":6367,"materia":"inf","nivel":2,"enunciado":"Pela LGPD, uma das bases legais para tratar dados pessoais é:","opcoes":["O consentimento do titular","A curiosidade do servidor","O pedido de qualquer empresa","A falta de reclamação do titular"],"explicacao":"Art. 7º, I, da Lei 13.709/2018. Há também outras bases, como obrigação legal."},{"id":6368,"materia":"inf","nivel":1,"enunciado":"O endereço IPv6 tem quantos bits?","opcoes":["128","32","64","256"],"explicacao":"O IPv4 tem 32 bits; o IPv6, 128."},{"id":6369,"materia":"inf","nivel":3,"enunciado":"No Linux, o comando chmod 755 relatorio.pdf dá:","opcoes":["Tudo ao dono; ler e executar ao grupo e aos outros","Tudo a todos os usuários do sistema","Só leitura ao dono; nada aos outros","Tudo ao grupo; só leitura aos outros"],"explicacao":"7 = rwx; 5 = r-x. A ordem é dono, grupo e outros."},{"id":6370,"materia":"inf","nivel":1,"enunciado":"Executar um programa suspeito num ambiente isolado para observar o que ele faz, sem afetar o sistema principal, é:","opcoes":["Sandboxing","Phishing","Spoofing","Defragmentação"],"explicacao":"A sandbox isola a execução justamente para não alterar o sistema real."},{"id":6371,"materia":"inf","nivel":1,"enunciado":"O antivírus que detecta uma ameaça nova pelo comportamento suspeito, sem conhecer sua assinatura, usa detecção:","opcoes":["Heurística","Por assinatura","Por backup","Por criptografia"],"explicacao":"A heurística analisa estrutura e comportamento do código."},{"id":6372,"materia":"inf","nivel":3,"enunciado":"No banco de dados, a propriedade em que a transação só é confirmada se todas as operações derem certo é a:","opcoes":["Atomicidade","Durabilidade","Isolamento","Normalização"],"explicacao":"É o \"tudo ou nada\" do ACID."},{"id":6373,"materia":"inf","nivel":2,"enunciado":"No modelo de nuvem IaaS, quem cuida do sistema operacional das máquinas virtuais é:","opcoes":["O cliente","Sempre o provedor","O fabricante do processador","Ninguém, pois não há sistema"],"explicacao":"No IaaS o provedor entrega servidores, rede e armazenamento; o resto fica com o cliente."},{"id":6374,"materia":"ia","nivel":1,"enunciado":"Numa rede adversarial generativa (GAN), os dois modelos que competem são:","opcoes":["Gerador e discriminador","Codificador e compilador","Servidor e cliente","Leitor e gravador"],"explicacao":"O gerador cria amostras; o discriminador tenta dizer se são reais."},{"id":6375,"materia":"ia","nivel":3,"enunciado":"Modelos de difusão geram imagens:","opcoes":["Removendo ruído passo a passo","Copiando fotos da internet","Seguindo só regras escritas à mão","Sorteando pixels sem treino"],"explicacao":"Aprendem a reverter um processo que adiciona ruído aos dados."},{"id":6376,"materia":"ia","nivel":1,"enunciado":"Modelo de IA treinado com dados amplos e que serve de base para muitas tarefas diferentes é chamado de:","opcoes":["Modelo fundacional","Modelo de regressão simples","Árvore de decisão","Planilha eletrônica"],"explicacao":"Exemplos são os grandes modelos de linguagem adaptados para usos específicos."},{"id":6377,"materia":"pen","nivel":1,"enunciado":"Um reincidente furta, sem violência, um bem de R$ 1.000. Ele tem direito ao furto privilegiado?","opcoes":["Não, o privilégio exige réu primário","Sim, porque o valor do bem é baixo","Sim, desde que devolva o bem depois","Só se a vítima perdoar o furto"],"explicacao":"Art. 155, § 2º: criminoso primário e coisa de pequeno valor."},{"id":6378,"materia":"pen","nivel":3,"enunciado":"Por descuido, um servidor conta ao irmão um segredo que soube por causa do cargo. Ele:","opcoes":["Não comete crime: não há violação de sigilo culposa","Comete violação de sigilo funcional na forma culposa","Comete prevaricação, por agir com descuido","Comete peculato culposo"],"explicacao":"O art. 325 do Código Penal só prevê a forma dolosa."},{"id":6379,"materia":"pen","nivel":3,"enunciado":"Depois de ser provocado de forma reprovável, Matheus xinga quem o provocou. Ele comete injúria, mas o juiz:","opcoes":["Pode deixar de aplicar a pena","Deve dobrar a pena","Deve trocar por difamação","Deve aplicar só multa"],"explicacao":"Art. 140, § 1º, I: perdão judicial quando o ofendido provocou diretamente a injúria."},{"id":6380,"materia":"pen","nivel":4,"enunciado":"Um reincidente é condenado a 6 anos de detenção. Ele começa a cumprir a pena no regime:","opcoes":["Semiaberto, pois detenção não começa no fechado","Fechado, por ser reincidente em crime doloso","Aberto, por se tratar de pena de detenção","Fechado, em presídio federal"],"explicacao":"Art. 33 do Código Penal: a detenção cumpre-se no semiaberto ou aberto, salvo regressão."},{"id":6381,"materia":"pen","nivel":4,"enunciado":"Revista publica, em reportagem, cena de nudez de uma mulher com recurso que impede totalmente identificá-la. Pelo art. 218-C, § 2º, do Código Penal, não há crime por:","opcoes":["Exclusão de ilicitude","Exclusão de culpabilidade","Extinção da punibilidade","Escusa absolutória"],"explicacao":"O próprio Código chama a hipótese de exclusão de ilicitude."},{"id":6382,"materia":"pen","nivel":2,"enunciado":"No crime de perseguição (stalking), o uso de arma pelo agente:","opcoes":["Aumenta a pena de metade","Torna o crime qualificado com pena dobrada","Não altera a pena","Transforma o crime em ameaça"],"explicacao":"Art. 147-A, § 1º, III, do Código Penal."},{"id":6383,"materia":"pen","nivel":4,"enunciado":"No crime de perseguição (art. 147-A do Código Penal), a ação penal é:","opcoes":["Pública condicionada à representação","Pública incondicionada, em qualquer caso","Privada, mediante queixa","Incondicionada se houver arma"],"explicacao":"Art. 147-A, § 3º: somente se procede mediante representação."},{"id":6384,"materia":"pen","nivel":4,"enunciado":"No roubo, o uso de um cabo de vassoura para ameaçar ou ferir a vítima:","opcoes":["Pode aumentar a pena, como emprego de arma branca","Nunca altera a pena, por não ser arma de verdade","Só aumenta a pena se houver perícia do objeto","Equivale ao uso de arma de fogo"],"explicacao":"Art. 157, § 2º, VII. Para o STJ, a apreensão e a perícia podem ser supridas por outras provas."},{"id":6385,"materia":"pen","nivel":1,"enunciado":"Num barco particular brasileiro em alto-mar, alguém comete crime. Aplica-se a lei penal brasileira?","opcoes":["Sim; o barco é tratado como território brasileiro","Não, porque o crime ocorreu fora do Brasil","Só se o barco fosse público ou militar","Só se a vítima for brasileira"],"explicacao":"Art. 5º, § 1º, do Código Penal: embarcações brasileiras privadas em alto-mar."},{"id":6386,"materia":"leg","nivel":4,"enunciado":"A regra de começar a pena em regime fechado, da Lei de Tortura, NÃO se aplica a quem:","opcoes":["Se omite diante da tortura que devia evitar","Tortura alguém sendo agente público","Tortura uma criança ou um adolescente","Tortura a vítima mediante sequestro"],"explicacao":"Art. 1º, § 7º, ressalva a omissão do § 2º, que tem pena de detenção."},{"id":6387,"materia":"leg","nivel":4,"enunciado":"O servidor condenado em definitivo por integrar organização criminosa perde o cargo e fica impedido de exercer função pública por:","opcoes":["8 anos após cumprir a pena","2 anos após a condenação","O dobro da pena aplicada","5 anos após a denúncia"],"explicacao":"Art. 2º, § 6º, da Lei 12.850/2013."},{"id":6388,"materia":"leg","nivel":2,"enunciado":"Na Lei de Drogas, NÃO é causa de aumento de pena do tráfico:","opcoes":["Ser o agente dependente químico","Ser o crime transnacional","Ocorrer perto de uma escola","Haver uso de arma de fogo"],"explicacao":"A dependência que tira a capacidade de entender pode até isentar de pena (art. 45)."},{"id":6389,"materia":"leg","nivel":4,"enunciado":"Na Lei de Drogas, apreendidos veículos usados no tráfico, o juiz deve determinar a alienação desses bens, exceto as armas, no prazo de:","opcoes":["30 dias da comunicação","5 dias da apreensão","1 ano após a sentença","90 dias da denúncia"],"explicacao":"Art. 61, § 1º, da Lei 11.343/2006."},{"id":6390,"materia":"leg","nivel":3,"enunciado":"Armas apreendidas, depois do laudo e quando não interessam mais ao processo, são enviadas pelo juiz ao Comando do Exército, para destruição ou doação, em até:","opcoes":["48 horas","24 horas","10 dias","30 dias"],"explicacao":"Art. 25 do Estatuto do Desarmamento."},{"id":6391,"materia":"leg","nivel":3,"enunciado":"O dono de empresa de segurança que não registra ocorrência nem avisa a Polícia Federal do furto de uma arma da empresa comete crime após:","opcoes":["24 horas do fato","48 horas do fato","7 dias do fato","30 dias do fato"],"explicacao":"Art. 13, parágrafo único, da Lei 10.826/2003."},{"id":6392,"materia":"leg","nivel":1,"enunciado":"Nos crimes ambientais da Lei 9.605/1998, a ação penal é:","opcoes":["Pública incondicionada","Privada","Pública condicionada à representação","Pública condicionada à requisição"],"explicacao":"Art. 26 da Lei 9.605/1998."},{"id":6393,"materia":"leg","nivel":2,"enunciado":"Pelo ECA, a criança só é encaminhada a acolhimento institucional com a Guia de Acolhimento expedida pela autoridade:","opcoes":["Judiciária","Policial","Do Conselho Tutelar","Do Ministério Público"],"explicacao":"Art. 101, § 3º, do ECA."},{"id":6394,"materia":"leg","nivel":3,"enunciado":"Pelo ECA, aos crimes praticados contra criança ou adolescente, a Lei dos Juizados Especiais (9.099/1995):","opcoes":["Não se aplica, seja qual for a pena","Aplica-se se a pena for até 2 anos","Aplica-se em todos os casos","Só não se aplica a crimes hediondos"],"explicacao":"Art. 226, § 1º, do ECA."},{"id":6395,"materia":"leg","nivel":4,"enunciado":"Pelo ECA, o juiz não aplica medida socioeducativa quando:","opcoes":["Não houver prova de que o adolescente participou","O adolescente confessar o ato infracional","A vítima pedir a absolvição do adolescente","O ato infracional for considerado grave"],"explicacao":"Art. 189 do ECA lista também a inexistência do fato e a falta de tipicidade."},{"id":6396,"materia":"leg","nivel":2,"enunciado":"Roubo com emprego de arma branca é crime hediondo?","opcoes":["Não; é hediondo, por exemplo, o roubo com arma de fogo","Sim, em qualquer caso de uso de arma branca","Sim, desde que a vítima sofra lesão leve","Só se o roubo for cometido durante a noite"],"explicacao":"Art. 1º, II, da Lei 8.072/1990."},{"id":6397,"materia":"leg","nivel":3,"enunciado":"Qual destes é crime hediondo?","opcoes":["Extorsão com restrição da liberdade da vítima","Roubo com emprego de faca de cozinha","Furto qualificado por escalada de muro","Lesão corporal leve"],"explicacao":"Art. 1º, III, da Lei 8.072/1990, incluído pelo Pacote Anticrime."},{"id":6398,"materia":"leg","nivel":2,"enunciado":"Na Lei Maria da Penha, havendo flagrante por descumprimento de medida protetiva, a fiança:","opcoes":["Só pode ser concedida pelo juiz","Pode ser dada pelo delegado","É proibida em qualquer caso","É dispensada"],"explicacao":"Art. 24-A, § 2º, da Lei 11.340/2006."},{"id":6399,"materia":"leg","nivel":1,"enunciado":"O crime de descumprir medida protetiva (art. 24-A da Lei Maria da Penha) só existe se a medida foi dada por juiz criminal?","opcoes":["Não; vale também se o juiz for cível","Sim, só se o juiz for criminal","Só se o MP tiver pedido a medida","Só se o juiz for da vara de família"],"explicacao":"Art. 24-A, § 1º: independe da competência civil ou criminal do juiz."},{"id":6400,"materia":"leg","nivel":3,"enunciado":"O preso que comete crime culposo e assim causa tumulto no presídio pode ir para o regime disciplinar diferenciado (RDD)?","opcoes":["Não; a lei exige crime doloso","Sim, em qualquer caso","Só se for preso definitivo","Sim, por até 6 meses"],"explicacao":"Art. 52 da LEP: fato previsto como crime doloso."},{"id":6401,"materia":"leg","nivel":1,"enunciado":"O regime disciplinar diferenciado (RDD) pode ser aplicado a preso provisório?","opcoes":["Sim, a provisórios e condenados","Não, só a condenados","Só a estrangeiros","Só a presos de presídio federal"],"explicacao":"Art. 52 da Lei de Execução Penal."},{"id":6402,"materia":"leg","nivel":2,"enunciado":"A prisão temporária por sequestro simples, que não é hediondo, dura:","opcoes":["5 dias, prorrogáveis por mais 5","30 dias, prorrogáveis por mais 30","10 dias, sem prorrogação","60 dias, sem prorrogação"],"explicacao":"Art. 2º da Lei 7.960/1989. Os 30 + 30 dias valem para hediondos."},{"id":6403,"materia":"leg","nivel":3,"enunciado":"A Polícia Federal pode investigar crimes pela internet que espalham ódio contra as mulheres quando houver repercussão:","opcoes":["Interestadual ou internacional","Apenas municipal","Só em período eleitoral","Só se a vítima for servidora"],"explicacao":"Lei 10.446/2002, alterada pela Lei 13.642/2018 (Lei Lola)."},{"id":6404,"materia":"ppen","nivel":2,"enunciado":"O agente público que reconhece um objeto de possível interesse para a perícia:","opcoes":["Fica responsável por preservá-lo","Pode levá-lo para a delegacia e liberá-lo","Pode descartá-lo se parecer sem valor","Deve entregá-lo à vítima"],"explicacao":"Art. 158-A, § 2º, do CPP."},{"id":6405,"materia":"ppen","nivel":3,"enunciado":"Pode o juiz trocar a preventiva por prisão domiciliar ao homem com filho de até 12 anos incompletos?","opcoes":["Sim, se for o único responsável pelos cuidados do filho","Sim, sempre, sem nenhuma outra condição","Só se a mãe da criança pedir por escrito","Não, a regra vale apenas para mulheres"],"explicacao":"Art. 318, VI, do CPP."},{"id":6406,"materia":"ppen","nivel":1,"enunciado":"A acareação pode ser feita entre:","opcoes":["Acusado e testemunha, entre outros","Somente duas testemunhas de acusação","Somente dois acusados do mesmo crime","Somente vítima e perito"],"explicacao":"Art. 229 do CPP: entre acusados, testemunhas, acusado e testemunha, e com o ofendido."},{"id":6407,"materia":"ppen","nivel":4,"enunciado":"No tráfico de pessoas, se o juiz não decidir em 12 horas o pedido de sinais de localização, o delegado:","opcoes":["Requisita direto às operadoras e avisa o juiz","Deve aguardar a decisão judicial, sem prazo","Pede ao Ministério Público que decida","Arquiva o pedido"],"explicacao":"Art. 13-B, § 4º, do CPP."},{"id":6408,"materia":"ppen","nivel":3,"enunciado":"Os sinais de localização obtidos pelo art. 13-B do CPP:","opcoes":["Não dão acesso ao conteúdo das comunicações","Liberam a escuta das ligações","Dão acesso às mensagens","Dispensam qualquer controle judicial"],"explicacao":"Art. 13-B, § 2º, I, do CPP."},{"id":6409,"materia":"ppen","nivel":2,"enunciado":"Quando alguém do povo comunica um crime de ação pública, o delegado manda instaurar inquérito:","opcoes":["Depois de verificar a procedência das informações","Imediatamente, sem checar nenhuma informação","Só depois de receber ordem escrita do juiz","Só se a vítima concordar"],"explicacao":"Art. 5º, § 3º, do CPP."},{"id":6410,"materia":"ppen","nivel":4,"enunciado":"A nulidade por ilegitimidade do representante da parte pode ser sanada:","opcoes":["A todo tempo, com a ratificação dos atos","Só até o encerramento da instrução","Só antes do oferecimento da denúncia","Nunca"],"explicacao":"Art. 568 do CPP."},{"id":6411,"materia":"ppen","nivel":1,"enunciado":"No Juizado Especial Criminal, a competência é do lugar:","opcoes":["Em que a infração foi praticada","Onde mora o autor do fato","Onde mora a vítima","Escolhido pela vítima"],"explicacao":"Art. 63 da Lei 9.099/1995."},{"id":6412,"materia":"const","nivel":3,"enunciado":"Desde a EC 131/2023, o brasileiro nato perde a nacionalidade quando:","opcoes":["Pede expressamente a perda, sem ficar apátrida","Adquire voluntariamente qualquer outra nacionalidade","Mora fora do Brasil por mais de 10 anos","É condenado por crime no exterior"],"explicacao":"Art. 12, § 4º, II, da Constituição."},{"id":6413,"materia":"const","nivel":4,"enunciado":"João só tem a nacionalidade brasileira e pede a perda dela antes de tentar a do Equador. O pedido:","opcoes":["Não pode ser aceito, pois o deixaria apátrida","Deve ser aceito na hora, por ser direito dele","Depende de sentença judicial transitada em julgado","Só vale se ele já morar fora"],"explicacao":"A Constituição ressalva as situações que gerem apatridia."},{"id":6414,"materia":"const","nivel":1,"enunciado":"Pela Constituição, o militar em serviço ativo:","opcoes":["Não pode se filiar a partido político","Pode fazer greve com aviso prévio","Pode se sindicalizar livremente","Pode fazer campanha partidária fardado"],"explicacao":"Art. 142, § 3º, IV e V."},{"id":6415,"materia":"const","nivel":3,"enunciado":"Para o STF, a lavratura do termo circunstanciado de ocorrência:","opcoes":["Não é exclusiva do delegado de polícia","É exclusiva do delegado de polícia","É exclusiva do juiz","É exclusiva do promotor"],"explicacao":"O TCO não é ato de investigação; outros órgãos podem lavrá-lo (STF, ADI 3.807)."},{"id":6416,"materia":"const","nivel":0,"enunciado":"O patrulhamento ostensivo das ferrovias federais cabe à:","opcoes":["Polícia Ferroviária Federal","Polícia Rodoviária Federal","Polícia Federal","Guarda Municipal"],"explicacao":"Art. 144, § 3º, da Constituição."},{"id":6417,"materia":"adm","nivel":2,"enunciado":"O atributo que permite ao ato administrativo se impor a terceiros, mesmo sem a concordância deles, é a:","opcoes":["Imperatividade","Autoexecutoriedade","Presunção de veracidade","Tipicidade"],"explicacao":"A autoexecutoriedade é poder executar o ato sem ir ao Judiciário."},{"id":6418,"materia":"adm","nivel":4,"enunciado":"A contratação que pode comprometer a segurança nacional, nos casos definidos pelo Ministério da Defesa, é licitação:","opcoes":["Dispensável","Inexigível","Obrigatória por concorrência","Proibida"],"explicacao":"Art. 75, VI, da Lei 14.133/2021."},{"id":6419,"materia":"adm","nivel":3,"enunciado":"Pela Lei 14.133/2021, para acessar o edital e os anexos no site oficial:","opcoes":["Não se exige registro nem identificação","Exige-se cadastro prévio no portal do órgão","Paga-se uma taxa de acesso aos documentos","Exige-se certificado digital"],"explicacao":"Art. 25, § 3º, da Lei 14.133/2021."},{"id":6420,"materia":"adm","nivel":1,"enunciado":"Policial civil e servidor concursado da Secretaria de Segurança ocupam cargo. Quem trabalha numa sociedade de economia mista ocupa:","opcoes":["Emprego público","Cargo efetivo","Cargo em comissão","Função de confiança"],"explicacao":"Nas estatais, o vínculo é celetista: emprego público."},{"id":6421,"materia":"adm","nivel":4,"enunciado":"Na nova Lei de Improbidade, o juiz pode condenar o réu por tipo diferente do indicado na petição inicial?","opcoes":["Não; essa decisão seria nula","Sim, livremente","Sim, se o MP concordar","Só no enriquecimento ilícito"],"explicacao":"Art. 17, § 10-F, I, da Lei 8.429/1992."},{"id":6422,"materia":"dh","nivel":1,"enunciado":"Pelo Código de Conduta da ONU para os Funcionários Responsáveis pela Aplicação da Lei, a força só pode ser usada:","opcoes":["Quando estritamente necessária e na medida exigida","Sempre que o suspeito for reincidente em crimes","À livre escolha do policial que está na ocorrência","Só depois de ordem judicial"],"explicacao":"Art. 3º do Código, adotado pela Resolução 34/169 (1979)."},{"id":6423,"materia":"dh","nivel":0,"enunciado":"Qual destes NÃO é direito previsto na Declaração Universal dos Direitos Humanos?","opcoes":["Fazer discurso de ódio contra outros","Liberdade de opinião e de expressão","Liberdade de pensamento e de religião","Direito à propriedade"],"explicacao":"A DUDH protege a liberdade de expressão, não ataques à honra e à dignidade."},{"id":6424,"materia":"dh","nivel":4,"enunciado":"Pelo Pacto de San José, não se impõe pena de morte a quem, no momento do crime, tinha mais de:","opcoes":["70 anos","60 anos","65 anos","80 anos"],"explicacao":"Art. 4º, 5. Também não se aplica a menores de 18 nem a grávidas."},{"id":6425,"materia":"dh","nivel":2,"enunciado":"Pelo Pacto de San José, as razões da detenção e a acusação formulada devem ser comunicadas:","opcoes":["Ao próprio preso","Só aos familiares","Só ao advogado","Só ao juiz"],"explicacao":"Art. 7º, 4, da Convenção Americana."},{"id":6426,"materia":"dh","nivel":3,"enunciado":"Pela Convenção da ONU contra a Tortura, o Brasil não deve extraditar alguém quando:","opcoes":["Há razões substanciais para crer que será torturado","O pedido de extradição vem de um país vizinho","O crime de que é acusado é contra o patrimônio","A pessoa é estrangeira"],"explicacao":"Art. 3º da Convenção contra a Tortura."},{"id":6427,"materia":"dh","nivel":4,"enunciado":"Pela Convenção dos Refugiados (1951), refugiado em situação regular pode ser expulso:","opcoes":["Por segurança nacional ou ordem pública, após processo","Em nenhuma hipótese, nem por segurança nacional","A qualquer momento, sem motivo e sem processo","Se pedir autorização de trabalho"],"explicacao":"Art. 32. O art. 33 proíbe devolvê-lo a onde corra risco (non-refoulement)."},{"id":6428,"materia":"dh","nivel":3,"enunciado":"Pelas Regras de Mandela, ao registrar a entrada de um preso, deve-se incluir:","opcoes":["Inventário dos seus bens pessoais","Lista das suas redes sociais","Sua renda mensal","Sua religião, obrigatoriamente"],"explicacao":"Regra 7 das Regras Mínimas da ONU para o Tratamento de Presos."},{"id":6429,"materia":"dh","nivel":1,"enunciado":"Pelas Regras de Mandela, presos provisórios devem ficar:","opcoes":["Separados dos condenados","Junto com os condenados","Em celas de segurança máxima","Sem direito a visita"],"explicacao":"Regra 11 das Regras Mínimas da ONU."},{"id":6430,"materia":"igual","nivel":0,"enunciado":"Raquel foi recusada numa vaga de emprego apenas por ser negra e nordestina. Pelo Estatuto da Igualdade Racial, ela sofreu:","opcoes":["Discriminação racial ou étnico-racial","Ação afirmativa prevista no Estatuto","Desigualdade de gênero no trabalho","Mero dissabor sem relevância"],"explicacao":"Art. 1º, parágrafo único, I, da Lei 12.288/2010."},{"id":6431,"materia":"ml","nivel":1,"enunciado":"Na identificação de ossadas, os ossos da pelve são muito úteis para estimar:","opcoes":["Sexo e idade","Tipo sanguíneo","Cor dos olhos","Profissão"],"explicacao":"A pelve tem diferenças marcantes entre homens e mulheres."},{"id":6432,"materia":"ml","nivel":3,"enunciado":"Instrumento perfurante de médio calibre, como um furador, costuma deixar ferida em forma de:","opcoes":["Casa de botão","Estrela","Meia-lua","Ponte"],"explicacao":"É a primeira lei de Filhos."},{"id":6433,"materia":"ml","nivel":2,"enunciado":"Pelo CPP, vestígio é todo objeto ou material bruto, visível ou latente, que:","opcoes":["Se relaciona à infração penal","Foi encontrado na casa do suspeito","Tem valor econômico","Foi fotografado pela imprensa"],"explicacao":"Art. 158-A, § 3º, do CPP."},{"id":6434,"materia":"port","nivel":1,"enunciado":"Na voz ativa, \"O crime costuma ser precedido por ameaças\" fica:","opcoes":["Ameaças costumam preceder o crime","O crime precede ameaças","Costuma-se preceder o crime","O crime costuma preceder ameaças"],"explicacao":"O agente da passiva (ameaças) vira sujeito na ativa."},{"id":6435,"materia":"port","nivel":2,"enunciado":"Em \"Excesso de informações, poucos empregos\", a vírgula pode ser trocada, sem mudar o sentido, por um conectivo:","opcoes":["Adversativo, como \"mas\"","Conclusivo, como \"logo\"","Explicativo, como \"pois\"","Alternativo, como \"ou\""],"explicacao":"Há oposição entre o excesso de um e a falta do outro."},{"id":6436,"materia":"port","nivel":4,"enunciado":"Em \"O objetivo é facilitar o acesso às informações\", a oração \"facilitar o acesso\" é:","opcoes":["Substantiva predicativa reduzida de infinitivo","Substantiva subjetiva reduzida de infinitivo","Adverbial final reduzida de infinitivo","Adjetiva reduzida de infinitivo"],"explicacao":"Ela funciona como predicativo do sujeito \"o objetivo\"."},{"id":6437,"materia":"port","nivel":3,"enunciado":"No texto, \"a cartilha\" é retomada depois por \"o material\". Esse recurso de coesão é o uso de:","opcoes":["Hiperônimo","Hipônimo","Antônimo","Parônimo"],"explicacao":"\"Material\" é termo mais geral que inclui a cartilha."},{"id":6438,"materia":"port","nivel":0,"enunciado":"Pelo Manual de Redação da Presidência, os assuntos dos expedientes oficiais devem ser tratados de forma:","opcoes":["Impessoal","Íntima","Humorística","Opinativa"],"explicacao":"A comunicação é feita em nome do serviço público."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
